import{z as n,x as A,o as s,c as d,q as l,j as o,D as e,d as E,s as i,S as p,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"KSM","description":"","frontmatter":{"title":"KSM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ksm.md","filePath":"cs/ksm.md","lastUpdated":1791413859000}'),m={name:"cs/ksm.md"};function B(c,a,C,S,h,M){const t=A("Mermaid");return s(),d("div",null,[a[2]||(a[2]=l('<h1 id="ksm" tabindex="-1">KSM <a class="header-anchor" href="#ksm" aria-label="Permalink to &quot;KSM&quot;">​</a></h1><div class="epigraph"><p>KSM 扫描已标记的匿名页，把内容相同的页合并成一页并写保护；再写则 COW 拆开。</p><footer>—— 据 Linux Kernel Samepage Merging 文档；Waldspurger 对 ESX 页共享的背景</footer></div><p><a href="/cs/thp">THP</a> 合并的是连续对齐页。<a href="/cs/fork">fork</a> 的 COW 只共享血统相同的页。虚拟机里许多页碰巧内容相同（全零、相同 libc）。缺口是 <strong>KSM</strong>：按内容合并。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>madvise(MADV_MERGEABLE)</code> 或 qemu 默认把客户机 RAM 标可合并。ksmd：校验和分桶，memcmp，合并后一页框、多 pte，<a href="/cs/rmap">rmap</a> 变长。缺口：CPU 扫描税；侧信道（合页证明内容相同）；与 NUMA（合并到哪一节点）。本课不把 KVM 气球提前写完。</p><p><span class="marginnote">全零页可走 zero page，不必 KSM。稳定树与不稳定树是实现分法。教学对象是「内容相等 ⇒ 可共享直到写」。</span></p><p><span class="marginnote">数字实例：一页 4 KB。把 200 台同镜像虚拟机里 1000 个内容相同的页并到同一页框，直接省下 \\((1000-1)\\times4\\,\\text{KB}\\approx4\\) MB 内存；代价是 ksmd 每轮要读完 pages_to_scan 个页做哈希与 memcmp，扫描越快省得越多、CPU 税也越重。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫描 → 哈希 → 比较 → 若等则把一页映射到另一页框，释放源，pte 写保护。写故障：分配新页拷开。对照 FS <a href="/cs/fs-snapshots">快照</a>：共享未改块；KSM 无「数据集根」，是全局扫描。对照 <a href="/cs/overlayfs">overlay</a>：一个文件树层，一个页内容。</p>',9)),(s(),o(p,null,{default:e(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCAN%5B%22ksmd%20%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20EQ%5B%22%E5%86%85%E5%AE%B9%E7%9B%B8%E5%90%8C%22%5D%0A%20%20EQ%20--%3E%20MERGE%5B%22%E5%85%B1%E9%A1%B5%E6%A1%86%E5%86%99%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20WR%5B%22%E5%86%99%22%5D%20--%3E%20COW%5B%22%E6%8B%86%E6%88%90%E7%A7%81%E6%9C%89%E9%A1%B5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"KSM 用 CPU 换 DRAM，适合同质 VM 密度。它改变「匿名页私有」的默认，引入信息泄漏面。不要写成去重存储产品。与 THP：大页内容更难吃进合并，常先拆再扫。",-1)),(s(),o(p,null,{default:e(()=>[i(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCAN%5B%22ksmd%20%E6%AF%8F%E8%BD%AE%E6%89%AB%20pages_to_scan%20%E9%A1%B5%22%5D%20--%3E%20CK%5B%22%E5%85%88%E7%AE%97%E6%A0%A1%E9%AA%8C%E5%92%8C%2C%20%E5%8F%98%E4%BA%86%E5%B0%B1%E9%87%8D%E6%96%B0%E5%85%A5%E6%A1%B6%22%5D%0A%20%20CK%20--%3E%20ST%5B%22%E7%A8%B3%E5%AE%9A%E6%A0%91%3A%20%E5%86%85%E5%AE%B9%E9%95%BF%E6%9C%9F%E6%B2%A1%E5%8F%98%E7%9A%84%E9%A1%B5%22%5D%0A%20%20CK%20--%3E%20UST%5B%22%E4%B8%8D%E7%A8%B3%E5%AE%9A%E6%A0%91%3A%20%E6%9C%80%E8%BF%91%E5%8F%98%E8%BF%87%E7%9A%84%E9%A1%B5%22%5D%0A%20%20ST%20--%3E%20CMP%5B%22memcmp%20%E7%B2%BE%E7%A1%AE%E6%AF%94%E5%AF%B9%22%5D%0A%20%20CMP%20--%3E%7C%22%E7%9B%B8%E5%90%8C%22%7C%20MERGE%5B%22%E5%B9%B6%E5%88%B0%E5%90%8C%E4%B8%80%E9%A1%B5%E6%A1%86%2C%20pte%20%E5%86%99%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E5%90%8C%22%7C%20UST%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">常见误区：初学者容易以为 KSM 只是省内存的纯优化。实际上「某页能否被合并」本身就是信息——攻击者可把自己的页改成候选内容再观察是否被合并、或测写故障延迟，从而探测别的虚拟机的内存内容，这类侧信道在云上必须认真对待。</span></p><p><span class="marginnote">术语翻译：写时拷贝（COW）就是「先让大家共用同一份，谁真的动手写，再当场给他复印一份私有的」。KSM 合并后的页都带着写保护，第一次写入触发缺页，内核才分配新页框把内容拷开，此后两页各走各路。</span></p><p>关闭 KSM 是安全/延迟场景的合理默认。</p><p>实现上：扫描速率用 pages_to_scan 调，太快伤延迟，太慢省不了内存。合并跨 NUMA 会把访问变成远程。关闭 merge 不会立刻拆页，已合并页要等写或换出。 读法上只引用<a href="/cs/thp">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>KSM</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 KSM Advisor 的全部自动调参。不保证跨 memcg 合并的记账细节在每版本一致。下一课内存紧张时的压缩缓存：zswap。</p><p>版本字段会变，课序钉的是机制对象「KSM」，不是某一主线内核的结构体名。 后课默认：相同匿名页可被扫成共享。换出前压缩进内存池，下一课 zswap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KSM 按内容合并匿名页，写则 COW。</li><li>省内存、耗 CPU、有侧信道。</li><li>zswap 是下一课。</li><li>出处：Linux KSM；Waldspurger ESX；Gorman。</li></ul>',11))])}const u=n(m,[["render",B]]);export{f as __pageData,u as default};
